const stick=$('#joystick');let stickPointer=null;function clearStick(){stickPointer=null;joystickVector={x:0,y:0};stick.querySelector('span').style.transform='translate(0,0)'}
stick.onpointerdown=e=>{if(!S||menu)return;e.preventDefault();stickPointer=e.pointerId;stick.setPointerCapture(e.pointerId);updateStick(e)};stick.onpointermove=e=>{if(e.pointerId===stickPointer)updateStick(e)};function updateStick(e){const r=stick.getBoundingClientRect(),x=(e.clientX-r.left-r.width/2)/(r.width*.35),y=(e.clientY-r.top-r.height/2)/(r.height*.35),len=Math.max(1,Math.hypot(x,y));joystickVector={x:x/len,y:y/len};stick.querySelector('span').style.transform=`translate(${joystickVector.x*29}px,${joystickVector.y*29}px)`}stick.onpointerup=stick.onpointercancel=clearStick;window.addEventListener('blur',clearStick);
document.addEventListener('visibilitychange',()=>{if(document.hidden)clearStick()});
