drawEnemy=function(e){if(e.dead&&e.deathT<=0)return;const moving=Math.hypot(e.dx||0,e.dy||0)>1,phase=e.gait||0,attack=e.strike?Math.sin(clamp(1-e.strike.t/.55,0,1)*Math.PI):0;g.save();g.translate(e.x,e.y);g.scale(e.x<active().x?1:-1,1);const scale=e.boss?1.9:e.elite?1.1:.85;g.scale(scale,scale);const col=ZONES[e.z].accent;if(e.dead)g.globalAlpha=.3;if(e.z>S.chapter&&!S.won)g.globalAlpha=.25;
 // Articulated claws and planted feet surround the painted monster torso.
 for(let side of [-1,1]){const step=moving?Math.sin(phase+side*Math.PI/2)*.55:0,k=limb(side*19,-27,18,step,col,12);limb(k.x,k.y,13,-step*.5,'#425253',10);const elbow=limb(side*26,-62,24,side*.75-attack*1.5,col,13);const hand=limb(elbow.x,elbow.y,20,side*.5-attack*1.9,col,10);for(let j=0;j<3;j++)line(hand.x-4+j*5,hand.y,hand.x-2+j*6,hand.y+11,'#e3d4ae',2)}g.restore();
 // Crop only the central body from the original painted creature, leaving animated limbs visible.
 if(characterAtlas.complete&&characterAtlas.naturalWidth){const sw=characterAtlas.naturalWidth/5,sh=characterAtlas.naturalHeight/2;g.save();g.translate(e.x,e.y-13);if(e.dead){g.globalAlpha=e.deathT/.65;g.rotate(1.1)}g.scale(e.x<active().x?1:-1,1);if(e.z>S.chapter&&!S.won)g.globalAlpha=.25;const h=e.boss?180:e.elite?97:80;g.drawImage(characterAtlas,e.z*sw+sw*.2,sh+sh*.05,sw*.6,sh*.9,-h*.32,-h,h*.64,h);g.restore();label(e.boss?ZONES[e.z].boss:(e.elite?'精英 · ':'')+['荆棘树妖','熔火魔卫','寒渊蛟灵','石甲守卫','蚀金魔卫'][e.z],e.x,e.y-(e.boss?215:114),col,e.boss?14:10);if(e.boss||e.hp<e.max){rr(e.x-30,e.y-(e.boss?204:104),60,5,2,'#172c29');rr(e.x-30,e.y-(e.boss?204:104),60*clamp(e.hp/e.max,0,1),5,2,'#d98d78')}if(e.boss&&S.kills[e.z]<ZONES[e.z].need){circle(e.x,e.y-90,105,'#9acecf66',2);label('灵脉屏障',e.x,e.y-232,'#a6d3d2',12)}if(e.shield>0)circle(e.x,e.y-80,90,'#a7d8e2',2);if(e.guardT>0)label('招架',e.x,e.y-135,'#efe1b8',12);if(e.burn>0)for(let j=0;j<5;j++)ellipse(e.x+Math.sin(j+time*3)*25,e.y-25-j*13,3,8,'#f4ab68');if(e.root>0)line(e.x-30,e.y,e.x+30,e.y,'#acd19a',4)}else previousEnemyDraw(e)};
