function taskState(){return S.fieldTasks[S.chapter]}
const originalValidate=validateSave;validateSave=function(v){if(!originalValidate(v))return false;if(v.fieldTasks!==undefined&&(!Array.isArray(v.fieldTasks)||v.fieldTasks.length!==5||v.fieldTasks.some(q=>!q||!Array.isArray(q.seen)||q.seen.length>5||q.seen.some((n,i)=>!Number.isInteger(n)||n<0||n>4||q.seen.indexOf(n)!==i)||typeof q.done!=='boolean'||!Number.isInteger(q.stage)||q.stage<0||q.stage>5)))return false;return true};
const v3Begin=begin;begin=function(data){v3Begin(data);S.fieldTasks=S.fieldTasks||FIELD_TASKS.map((_,i)=>({seen:[],done:!!S.bosses[i],stage:0}));for(let a of actors){a.gait=0;a.motion=0}for(let e of enemies)e.gait=0;logMessage('行者之约：跑步、挥砍与骑乘均有独立关节动作。点击「旅途」查看可选场景任务。')};
function completeFieldTask(){const q=taskState();if(q.done)return;q.done=true;grantGold25(100+S.chapter*35);awardXp(90+S.chapter*30);grantPotions25(2);addItem(S.chapter,true);logMessage('场景任务完成！获得经验、金币、装备与两瓶药剂。');fx(active().x,active().y,100,'#d8d69b');saveGame(false);refreshBars()}
function fieldInteract(){if(!S||menu||S.won)return false;const q=taskState(),z=S.chapter,t=FIELD_TASKS[z];if(q.done)return false;const n=t.points.findIndex(p=>dist(active(),p)<100);if(n<0)return false;
 if(z===0){if(n<3){if(!q.seen.includes(n)){q.seen.push(n);logMessage('采到灵草 '+q.seen.length+'/3')}else logMessage('这里的灵草已经采过。')}else if(q.seen.length>=3)completeFieldTask();else logMessage('侦察员：先找三株灵草！点心不是药。')}
 if(z===1){if(!q.seen.includes(n)){q.seen.push(n);const p=t.points[n];for(let j=0;j<2;j++){const e=makeEnemy(z,false,p.x+Math.cos(j*Math.PI)*70,p.y+60,'beacon'+n+j);e.respawn=9999;enemies.push(e)}logMessage('信标点亮！熔火护卫被惊动了。');if(q.seen.length===3)completeFieldTask()}else logMessage('这座信标已点燃。')}
 if(z===2){if(n===q.stage){q.stage++;logMessage('灵铃共鸣 '+q.stage+'/3');if(q.stage===3)completeFieldTask()}else{q.stage=0;const e=makeEnemy(z,false,active().x+90,active().y,'bell'+Math.floor(time));enemies.push(e);logMessage('错音惊醒了湖中守卫！重新按水→木→火敲铃。')}}
 if(z===3){if(n<3){if(!q.seen.includes(n)){q.seen.push(n);logMessage('取回补给 '+q.seen.length+'/3')}}else if(q.seen.length===3){for(let a of actors)if(owned(a.i)&&a.hp>0)a.hp=stats(a.i).hp;completeFieldTask()}else logMessage('驿站还在等三箱补给。')}
 if(z===4){if(S.active!==n)logMessage('需要切换到'+HEROES[n].element+'属性伙伴（键盘 '+(n+1)+'）。');else if(!q.seen.includes(n)){q.seen.push(n);logMessage(HEROES[n].element+'印共鸣！');if(q.seen.length===5)completeFieldTask()}}
 saveGame(false);return true}
