const v3Update=update;update=function(dt){const old=actors.map(a=>({x:a.x,y:a.y})),enemyOld=enemies.map(e=>({x:e.x,y:e.y}));v3Update(dt);if(!S||menu)return;actors.forEach((a,i)=>{const d=old[i]?Math.hypot(a.x-old[i].x,a.y-old[i].y):0;a.motion=d/dt;a.gait=(a.gait||0)+d/(petOf(i)?20:12)});enemies.forEach((e,i)=>{e.dx=e.x-(enemyOld[i]?.x||e.x);e.dy=e.y-(enemyOld[i]?.y||e.y);e.gait=(e.gait||0)+Math.hypot(e.dx,e.dy)/15});if(!S.won&&!taskState().done){const t=FIELD_TASKS[S.chapter],n=t.points.findIndex(p=>dist(active(),p)<100);if(n>=0)$('#hint').textContent='F 互动 · '+t.labels[n]+' · '+t.name}};
const v3Draw=draw;draw=function(){v3Draw();if(!S)return;g.save();g.translate(-cam.x,-cam.y);if(!S.won){const t=FIELD_TASKS[S.chapter],q=taskState();if(q&&!q.done)for(let [i,p]of t.points.entries()){if(q.seen.includes(i))continue;circle(p.x,p.y,23+Math.sin(time*3+i)*2,'#d8ce8d88',1);if(S.chapter===0&&i<3){for(let j=0;j<4;j++)line(p.x,p.y,p.x+Math.sin(j*2)*13,p.y-17-Math.cos(j*2)*6,'#a4cda2',3);ellipse(p.x,p.y-22,4,5,'#b6d9dc')}else{poly([[p.x-7,p.y],[p.x-10,p.y-25],[p.x,p.y-40],[p.x+10,p.y-25],[p.x+7,p.y]],S.chapter===2?['#8ecfe8','#91c995','#efa480'][i]:'#ae9f73');ellipse(p.x,p.y-30,3,5,'#eee3b6')}label(t.labels[i],p.x,p.y-50,'#e5dba7',11)}}for(let j=0;j<24;j++){const x=(j*163+Math.sin(time*.4+j)*25)%WW,y=(j*227+time*3)%WH;ellipse(x,y,1.5,1.5,'#e8d785'+Math.floor(80+Math.sin(time*2+j)*60).toString(16).padStart(2,'0'))}g.restore();if(menu==='gallery')renderGallery()};
function journeyPanel(){if(!S)return;const t=FIELD_TASKS[S.chapter],q=taskState();showDialog(panelHead('旅途 · '+t.name)+'<p>'+t.story+'</p><p>场景任务为可选支线，不阻挡原有首领与章节。</p><p>'+(q.done?'已完成，奖励已领取。':'提示：寻找地图上的金色光圈，靠近后按 F。已互动 '+q.seen.length+' 处。')+'</p><div class="actions"><button id="followTask" class="primary">追踪附近目标</button><button id="showGallery">查看动作</button></div>');$('#followTask').onclick=()=>{let n=t.points.findIndex((p,i)=>!q.seen.includes(i));if(S.chapter===2)n=Math.min(2,q.stage);closeDialog();if(!q.done&&n>=0){destination={...t.points[n]};logMessage('开始前往 '+t.labels[n]+'，途中请注意敌人。')}};$('#showGallery').onclick=galleryPanel}
