let selection=[],savedGroups=[[],[],[]],formation='wedge',selectionDrag=null,commandMode='move',novaFx=[],ambientClock=0,renderClock=0;
function currentMap(){return S?.map||0}
function mapUnlocked(id){if(!S)return id===0||id===1;return id===0||id<6&&id<=S.chapter+1||id===6&&(S.won||Math.max(...S.heroes.filter(h=>h.unlocked).map(h=>h.lv))>=30)}
function mapPortals(){return currentMap()===0?HUB_PORTALS:[{x:500,y:650,to:0},...(currentMap()!==6?[{x:4250,y:2820,to:6}]:[])]}
function mapObstacles(id=currentMap()){if(!id)return [];const walls=[{x:1590,y:130,w:180,h:1040,kind:'river'},{x:1590,y:1540,w:180,h:1430,kind:'river'},{x:2720,y:650,w:100,h:650,kind:'wall'},{x:2720,y:1580,w:100,h:1000,kind:'wall'},{x:2820,y:650,w:800,h:100,kind:'wall'},{x:2820,y:2480,w:480,h:100,kind:'wall'}];if(id===4||id===6)walls.push({x:2040,y:1980,w:500,h:100,kind:'wall'},{x:2050,y:380,w:480,h:100,kind:'wall'});return walls}
function walkable(x,y,r=18){if(x<65||y<125||x>WW-65||y>WH-50)return false;return !mapObstacles().some(o=>x+r>o.x&&x-r<o.x+o.w&&y+r>o.y&&y-r<o.y+o.h)}
function findPath(from,to){const size=80,cols=WW/size,rows=WH/size,start={x:Math.floor(from.x/size),y:Math.floor(from.y/size)},goal={x:clamp(Math.floor(to.x/size),1,cols-2),y:clamp(Math.floor(to.y/size),2,rows-2)};if(!walkable(to.x,to.y))return [];
 const key=p=>p.y*cols+p.x,open=[{...start,cost:0,h:Math.abs(start.x-goal.x)+Math.abs(start.y-goal.y)}],came=new Map(),costs=new Map([[key(start),0]]);let finish=null,limit=0;
 while(open.length&&limit++<3500){open.sort((a,b)=>(a.cost+a.h)-(b.cost+b.h));const n=open.shift();if(n.x===goal.x&&n.y===goal.y){finish=n;break}for(const [dx,dy]of [[1,0],[-1,0],[0,1],[0,-1]]){const p={x:n.x+dx,y:n.y+dy};if(!walkable(p.x*size+size/2,p.y*size+size/2,25))continue;const id=key(p),cost=n.cost+1;if(cost>=(costs.get(id)??Infinity))continue;costs.set(id,cost);came.set(id,n);open.push({...p,cost,h:Math.abs(p.x-goal.x)+Math.abs(p.y-goal.y)})}}
 if(!finish)return [];const points=[{x:to.x,y:to.y}];let p=finish;while(key(p)!==key(start)){points.push({x:p.x*size+40,y:p.y*size+40});p=came.get(key(p));if(!p)break}return points.reverse()}
baseMove=function(a,dx,dy,speed,dt){const length=Math.hypot(dx,dy);if(length<.001)return;const x=clamp(a.x+dx/length*speed*dt,65,WW-65),y=clamp(a.y+dy/length*speed*dt,125,WH-50);if(walkable(x,y)){a.x=x;a.y=y}else if(walkable(x,a.y))a.x=x;else if(walkable(a.x,y))a.y=y;if(Math.abs(dx)>.1)a.face=dx>0?1:-1;a.walk+=speed*dt*.045};
function formationOffset(index,total){if(formation==='line')return {x:(index-(total-1)/2)*68,y:0};if(formation==='circle'){const angle=index*Math.PI*2/Math.max(1,total);return{x:Math.cos(angle)*82,y:Math.sin(angle)*62}}return{x:(index%2?1:-1)*Math.ceil(index/2)*55,y:Math.ceil(index/2)*60}}
function selectedActors(){return actors.filter(a=>selection.includes(a.i)&&owned(a.i)&&a.hp>0)}
function selectUnits(ids,focus=true){selection=[...new Set(ids)].filter(i=>Number.isInteger(i)&&i>=0&&i<5&&owned(i)&&actors[i].hp>0);if(!selection.length&&active()?.hp>0)selection=[S.active];if(focus&&selection.length&&!selection.includes(S.active))S.active=selection[0];refreshOrderBar()}
function commandUnits(kind,point=null){const list=selectedActors();for(let [n,a]of list.entries()){if(kind==='hold'){a.order={kind:'hold'};a.path=[];continue}if(kind==='follow'){a.order={kind:a.i===S.active?'hold':'follow'};a.path=[];continue}const offset=formationOffset(n,list.length),target={x:clamp(point.x+offset.x,80,WW-80),y:clamp(point.y+offset.y,150,WH-80)},path=findPath(a,target);if(!path.length){logMessage('目标被河流或城墙阻挡，请选择可通行位置。');continue}a.order={kind,x:target.x,y:target.y};a.path=path}destination=null;refreshOrderBar()}
function moveAlong(a,dt){if(!a.path?.length)return false;const p=a.path[0];if(dist(a,p)<12){a.path.shift();return a.path.length>0}move(a,p.x-a.x,p.y-a.y,stats(a.i).speed,dt);return true}
let lastOrderKey='';function refreshOrderBar(){if(!S)return;const key=selection.join(',')+formation;if(key===lastOrderKey)return;lastOrderKey=key;$('#orderBar').innerHTML=`<span>${selection.map(i=>HEROES[i].element).join(' · ')||'单控'} · ${{line:'横队',circle:'环形',wedge:'楔形'}[formation]}</span><button data-order="all">全选</button><button data-order="hold">驻守</button><button data-order="follow">跟随</button><button data-order="attackmove">进攻移动</button>`;$('#orderBar').querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>{const k=b.dataset.order;if(k==='all')selectUnits(actors.filter(a=>owned(a.i)).map(a=>a.i));else if(k==='attackmove'){commandMode='attackmove';logMessage('点击地面下达进攻移动命令。')}else commandUnits(k)})}
