const pauseV4=pausePanel;pausePanel=function(){pauseV4();const container=$('#dialog');container.insertAdjacentHTML?.('beforeend','<div class="actions"><button id="pauseCareer">百级转职</button><button id="pauseWorld">传送地图</button><button id="pauseSquad">编队命令</button><button id="pauseFx">切换特效档位</button><button id="pauseAscend">释放觉醒技 T</button></div>');$('#pauseCareer').onclick=careerPanel;$('#pauseWorld').onclick=worldPanel;$('#pauseSquad').onclick=squadPanel;$('#pauseFx').onclick=()=>{S.fxQuality=S.fxQuality==='low'?'high':'low';saveGame(false);logMessage('特效档位：'+(S.fxQuality==='low'?'流畅':'绚丽'))};$('#pauseAscend').onclick=()=>{closeDialog();ascensionSkill()}};
const introV4=intro;intro=function(){introV4();const h=$('#dialog').querySelector('h2');if(h)h.textContent='五行战记：诸界远征';};
let orderRestoreInProgress=false;
const saveBeforeOrders=saveGame;saveGame=function(announce=true){if(!orderRestoreInProgress&&S&&actors.length===5){S.unitPositions=actors.map(a=>({x:a.x,y:a.y}));S.unitOrders=actors.map(a=>({kind:a.order?.kind||'hold',...(a.order?.x!==undefined?{x:a.order.x,y:a.order.y}:{})}));S.groups=savedGroups.map(g=>[...g]);S.formation=formation}return saveBeforeOrders(announce)};
const beginBeforeOrders=begin;begin=function(data){const positions=data.unitPositions?.map(p=>({...p})),orders=data.unitOrders?.map(o=>({...o}));const copy=JSON.parse(JSON.stringify(data));if(copy.map===undefined)copy.position={x:CAMP.x,y:CAMP.y+40};orderRestoreInProgress=true;try{beginBeforeOrders(copy)}finally{orderRestoreInProgress=false}if(positions)actors.forEach((a,i)=>{const p=positions[i];if(p&&walkable(p.x,p.y)){a.x=p.x;a.y=p.y;const order=orders?.[i];a.order=order||{kind:'hold'};if(order?.x!==undefined&&(order.kind==='move'||order.kind==='attackmove'))a.path=findPath(a,order)}});cam.x=clamp(active().x-VW/2,0,WW-VW);cam.y=clamp(active().y-VH/2,0,WH-VH);log=[];logMessage('诸界远征：独立地图、单控编队、百级转职与灵兽合体已启程。')};
const validateBeforeOrders=validateSave;validateSave=function(v){if(!validateBeforeOrders(v))return false;if(v.unitPositions!==undefined&&(!Array.isArray(v.unitPositions)||v.unitPositions.length!==5||v.unitPositions.some(p=>!p||!Number.isFinite(p.x)||!Number.isFinite(p.y)||p.x<0||p.x>WW||p.y<0||p.y>WH)))return false;if(v.unitOrders!==undefined&&(!Array.isArray(v.unitOrders)||v.unitOrders.length!==5||v.unitOrders.some(o=>!o||!['hold','follow','move','attackmove'].includes(o.kind)||o.x!==undefined&&(!Number.isFinite(o.x)||!Number.isFinite(o.y)||o.x<0||o.x>WW||o.y<0||o.y>WH))))return false;return true};
const summonV4=summonAdds;summonAdds=function(e){const count=enemies.length;summonV4(e);for(const a of enemies.slice(count)){a.map=e.map;a.rift=!!e.rift}};
const terrainAtlas=new Image();terrainAtlas.src='assets/terrain-v5.png';const terrainPatterns=new Map();
