const miniBefore11=drawMini;drawMini=function(){miniBefore11();if(!S)return;const sx=190/WW,sy=120/WH;if(currentMap()===0){mg.strokeStyle='#d7be8066';mg.lineWidth=2;for(const road of SCENES11.roads){mg.beginPath();road.forEach(([x,y],i)=>i?mg.lineTo(x*sx,y*sy):mg.moveTo(x*sx,y*sy));mg.stroke()}for(const n of SCENES11.npcs){mg.fillStyle='#a0e2db';mg.fillRect(n.x*sx-1.5,n.y*sy-1.5,3,3)}for(const e of enemies)if(e.map===0&&!e.dead){mg.fillStyle=e.rank8?'#d0a6f6':'#e89a84';mg.fillRect(e.x*sx-1,e.y*sy-1,e.rank8?3:2,e.rank8?3:2)}}for(const c of SCENES11.chests)if(c.map===currentMap()&&!S.treasure11.includes(c.id)&&(!c.hidden||dist(active(),c)<240)){mg.fillStyle='#f2d18a';mg.fillRect(c.x*sx-1.5,c.y*sy-1.5,3,3)}};
