baseDraw=function(){g.clearRect(0,0,VW,VH);if(!S)cam={x:0,y:0};g.save();g.translate(-cam.x,-cam.y);drawMap();const queue=[];for(const d of decor){if(!seen11(d,180))continue;if(currentMap()===0&&(d.x<1120&&d.y<1160||SCENES11.spawns.some(p=>Math.hypot(p[0]-d.x,p[1]-d.y)<65)||SCENES11.props.some(p=>dist(d,p)<150)||SCENES11.chests.some(c=>c.map===0&&dist(d,c)<65)))continue;queue.push({y:d.y,draw:()=>{if(d.type<3){const fade=S&&actors.some(a=>owned(a.i)&&a.hp>0&&Math.abs(a.x-d.x)<60*d.scale&&a.y>d.y-150*d.scale&&a.y<d.y+14);g.save();g.globalAlpha=fade?.28:1;tree(d.x,d.y,d.scale);g.restore()}else if(d.type<5)rock(d.x,d.y,d.scale*.6);else{ellipse(d.x,d.y,10,4,'#172c2577');for(let j=0;j<3;j++){line(d.x,d.y,d.x+Math.sin(j*2+visualClock11*.5)*9,d.y-9-j*3,'#728e64',2)}}}})}if(currentMap()===0)for(const p of SCENES11.props)if(seen11(p,p.h))queue.push({y:p.y,draw:()=>drawProp11(p)});for(const n of sceneNpcs11())if(seen11(n))queue.push({y:n.y,draw:()=>drawNpc11(n)});for(const c of SCENES11.chests)if(c.map===currentMap()&&seen11(c))queue.push({y:c.y,draw:()=>drawChest11(c)});for(const e of enemies)if(e.map===currentMap()&&(!e.dead||e.deathT>0)&&seen11(e,250))queue.push({y:e.y,draw:()=>drawEnemy(e)});for(const a of actors)if(S&&owned(a.i)&&seen11(a))queue.push({y:a.y,draw:()=>drawHero(a)});if(typeof companionQueue11==='function')companionQueue11(queue);if(typeof detailQueue12==='function')detailQueue12(queue);queue.sort((a,b)=>a.y-b.y);for(const item of queue)item.draw();for(const e of effects){if(!seen11(e,e.r||120))continue;const p=1-e.t/e.max;g.globalAlpha=Math.min(1,e.t*4);if(e.type==='bolt'){line(e.x,e.y,e.tx,e.ty,e.color,2);ellipse(e.tx,e.ty,5,5,e.color)}else if(e.type==='slash'){g.strokeStyle=e.color;g.lineWidth=4;g.beginPath();g.arc(e.x,e.y,35+p*25,-1.5,.8);g.stroke()}else circle(e.x,e.y,e.r*(.3+p*.7),e.color,Math.max(1,5*(1-p)));g.globalAlpha=1}for(const p of particles11){if(!seen11(p,40))continue;g.globalAlpha=clamp(p.t/p.max,0,1);if(p.element===3)flame8(p.x,p.y,p.size*.6,visualClock11+p.t);else if(p.element===2)poly([[p.x,p.y-5],[p.x+3,p.y],[p.x,p.y+5],[p.x-3,p.y]],p.color);else if(p.element===1)ellipse(p.x,p.y,p.size,p.size*.45,p.color,visualClock11);else line(p.x,p.y,p.x-p.vx*.035,p.y-p.vy*.035,p.color,p.size*.7);g.globalAlpha=1}for(const l of loot)if(seen11(l)){ellipse(l.x,l.y-l.t*15,4,7,'#e4c478')}for(const n of numbers)if(seen11(n,30)){g.globalAlpha=Math.min(1,n.t*2);label(n.text,n.x,n.y,n.color,n.text.includes('暴击')?16:13);g.globalAlpha=1}if(destination){floorRing11(destination.x,destination.y,15,'#e4d699');}if(S?.fxQuality!=='low'){for(let j=0;j<settings11().ambient;j++){const x=cam.x+(j*197+Math.sin(visualClock11*.3+j)*40)%VW,y=cam.y+(j*137+visualClock11*8)%VH;g.globalAlpha=.2+Math.sin(visualClock11+j)*.15;ellipse(x,y,1,2,currentMap()===2?'#f8c48e':'#e1dca6')}g.globalAlpha=1}g.restore();const shade=g.createRadialGradient(VW*.5,VH*.4,VW*.27,VW*.5,VH*.5,VW*.75);shade.addColorStop(0,'#0b162000');shade.addColorStop(1,'#06132199');g.fillStyle=shade;g.fillRect(0,0,VW,VH);drawMini()};
const renderBefore11=draw;draw=function(){const now=performance.now(),cfg=settings11();if(lastRender11&&now-lastRender11<1000/cfg.fps-1)return;lastRender11=lastRender11?now-((now-lastRender11)%(1000/cfg.fps)):now;const start=performance.now();renderClock=visualClock11-1/60;renderBefore11();if(S&&!menu){const elapsed=performance.now()-start;perfSamples11.push(elapsed);if(perfSamples11.length>240)perfSamples11.shift();fpsWindow11.frames++;if(!fpsWindow11.at)fpsWindow11.at=now;if(now-fpsWindow11.at>=1000){fpsWindow11.fps=Math.round(fpsWindow11.frames*1000/(now-fpsWindow11.at));fpsWindow11.ms=perfSamples11.reduce((a,b)=>a+b,0)/perfSamples11.length;fpsWindow11.frames=0;fpsWindow11.at=now}}};

