fuseGems10=function(materials,source=cryptoRoll10,request){if(typeof source!=='function')return false;return commit17('gem-fusion',request,()=>{const p=gemFusionPreview10(materials);if(!p.valid)return false;const rolls=rolls10(source,1);if(!rolls)return false;const success=rolls[0]<p.success,consumed=success?p.materials:p.materials.slice(1),changes=consumed.map(g=>({...g,count:resourceFree17()?0:-1}));if(success)changes.push({...p.result,count:1});const next=forgeInventory7(changes);if(!next||!pay17({gold:p.cost,iron:p.iron}))return false;S.gems=next;S.gemPity10[p.level]=success?0:Math.min(9999,(S.gemPity10[p.level]||0)+1);if(success&&p.recipe&&!S.discoveredRecipes10.includes(p.recipe.id))S.discoveredRecipes10.push(p.recipe.id);audit10('gem-fusion',(success?'凝成 '+gemName(p.result):'熔炼失败：主石保留，另外两石消耗')+'；金币-'+p.cost+'，灵铁-'+p.iron+'，概率'+(p.success*100).toFixed(2)+'%',true);return {success,gem:success?p.result:null,preview:p}})};
