function stepBatch17(source=cryptoRoll10){const b=batchRun17;if(!b?.running)return false;if(!S||S.worldId10!==b.world||S.revision10!==b.revision||S.active!==b.hero||staleSave10||!diskMatches10()){stopBatch17('存档或操作者变化，已安全暂停');return false}for(let n=0;n<RULES17.furnace.chunk&&b.running;n++){if(b.attempts>=b.config.count){stopBatch17('已完成设定次数');break}const g=batchCandidate17(b.config);if(!g){stopBatch17('达到目标，或没有满足筛选与保留数量的三枚材料');break}const p=gemFusionPreview10([g,g,g]);if(!p.valid){stopBatch17(p.reason);break}const r=fuseGems10([g,g,g],source,quote10());if(!r){stopBatch17('结算未完成，已停止');break}b.attempts++;b[r.success?'successes':'failures']++;b.gold+=resourceFree17()?0:p.cost;b.iron+=resourceFree17()?0:p.iron;b.embers=(b.embers||0)+(resourceFree17()?0:p.embers||0);b.cores=(b.cores||0)+(resourceFree17()?0:p.cores||0);if(r.gem){const k=gemName(r.gem);b.results[k]=(b.results[k]||0)+1}S.batch17={status:'running',attempts:b.attempts,successes:b.successes,failures:b.failures,gold:b.gold,iron:b.iron,embers:b.embers||0,cores:b.cores||0,config:b.config,world:b.world,hero:b.hero,results:b.results};saveGame(false);b.revision=S.revision10}paintBatch17();if(b.running)scheduleBatch17();return true}
function paintBatch17(){const b=batchRun17||S?.batch17,n=$('#batchProgress17');if(!b||!n)return;n.textContent=`${b.running?'熔炼中':'已暂停'} · ${b.attempts}/${b.config?.count||b.attempts} 次 · 成功 ${b.successes} / 失败 ${b.failures} · 消耗 ${b.gold.toLocaleString()} 金币、${b.iron} 灵铁、${b.embers||0} 灵焰、${b.cores||0} 星核 · ${b.reason}。${Object.entries(b.results||{}).slice(-8).map(([k,v])=>k+' ×'+v).join('；')}`}
