function hasDivine17(i){if(!S||!int10(i,0,4)||!owned(i))return false;const h=S.heroes[i];return [...h.gear.filter(Boolean).flatMap(it=>it.sockets||[]),...(h.altar10||[])].some(g=>g?.type===23&&gemValid(g))}
function divineBoost17(p,kind,owner){const high=kind==='gem'?p.level>=RULES17.divine.gemThreshold:p.quality>=RULES17.divine.petThreshold;const active=owner===S.active&&actors[owner]?.hp>0&&hasDivine17(owner);return {...p,normalSuccess:p.success,godstone17:!!(high&&active),success:high&&active?Math.max(p.success,RULES17.divine.floor):p.success}}
function divinePreview17(materials){let reason='';if(!Array.isArray(materials)||materials.length!==5||materials.some(g=>!gemValid(g)||g.type===23||g.level!==11||gemElements10(g).length!==1))reason='每槽需一枚最高Lv.11的单元素宝石。';else if(new Set(materials.map(g=>gemElements10(g)[0])).size!==5)reason='必须金、木、水、火、土各一枚。';else if(materials.some(g=>gemProtected17(g)||gemProtected17(gemBag().find(x=>gemKey17(x)===gemKey17(g)))))reason='材料已锁定、收藏或绑定。';else if(countMaterials10(materials).some(g=>usableGem17(g)<g.count))reason='包裹中没有足量可用的五行材料。';const attempts=S.divineForge17.attempts,scale=1+Math.min(10,attempts)*.3,cost={gold:Math.round(RULES17.divine.gold*scale),iron:Math.round(RULES17.divine.iron*scale),embers:Math.ceil(RULES17.divine.embers*scale),cores:RULES17.divine.cores};if(!reason&&!advancedMarket17())reason='需救出五位英雄并实际击败前四章首领。';if(!reason&&Math.max(...S.heroes.map(heroCount10))<1)reason='需至少一位英雄完成一次进阶。';if(!reason&&Date.now()<S.divineForge17.readyAt)reason='神炉冷却中，剩余'+Math.ceil((S.divineForge17.readyAt-Date.now())/1000)+'秒。';if(!reason&&!canPay17(cost))reason='金币、灵铁、灵焰或星核不足。';const luck=sharedLuck10(),success=clamp(RULES17.divine.base*luck.factor,RULES17.divine.base,RULES17.divine.cap),gem={type:23,level:11,quality:6,divine17:true};if(!reason&&!forgeInventory7([{...gem,count:1}]))reason='神石堆叠或宝石包裹已满。';return {valid:!reason,reason,success,base:RULES17.divine.base,cap:RULES17.divine.cap,luck:luck.total,cost,gem,attempts}}
function refineDivine17(materials,source=cryptoRoll10,request){return commit17('divine-forge17',request,()=>{const p=divinePreview17(materials);if(!p.valid)return false;const random=rolls10(source,1);if(!random)return false;const success=random[0]<p.success;const next=success?forgeInventory7([...materials.map(g=>({...g,count:resourceFree17()?0:-1})),{...p.gem,count:1}]):gemBag().map(g=>({...g}));if(!next||!pay17(p.cost))return false;S.gems=next;S.divineForge17.attempts++;S.divineForge17.readyAt=Date.now()+RULES17.divine.cooldown;audit10('divine-forge17',(success?'五行归一，五行神石诞生。':'神炉熄火，五枚主材料完整保留，催化材料与费用消耗。')+' 概率'+(p.success*100).toFixed(2)+'%',true);return {success,gem:success?p.gem:null,preview:p}})}
function divinePanel17(){panelContext7={key:'divine17',args:[]};showDialog(panelHead('五行熔炼殿 · 五行神炉')+furnaceNav17()+`<div class="atelier17 divine-room17"><div class="divine-art17"></div><section><h3>五行归一 · 隐藏神石</h3><p>仅此炉产出；普通商店与怪物不会掉落。单元素最高级宝石，五行各一。</p><div class="slots17 five17">${[0,1,2,3,4].map(el=>`<label>${['金','木','水','火','土'][el]}<select id="divineSlot${el}"><option value="">请选择</option>${gemOptions17(g=>g.level===11&&gemElements10(g).length===1&&gemElements10(g)[0]===el&&!gemProtected17(g))}</select></label>`).join('')}</div><div id="divinePreview17"></div><button id="divineDo17" class="primary">点燃五行炉</button><p id="divineResult17" role="status"></p></section></div><p>失败保留五枚宝石，消耗金币、灵铁、灵焰和星核；连续尝试成本上升，每次冷却15秒。基础5%，共享幸运修正，封顶15%。神石不提高自身炼制概率。</p><p>装备神石：攻击+50,000、生命+350,000、法力+50,000、法术+60,000、护甲+2,500、幸运+1,000；实际伤害汲取10%，附近友军获得非叠加光环与周期护盾。同一英雄重复装备不会叠加神石本体属性。</p><p>当前选中且装备神石的英雄主持高阶宝石（目标Lv.8+）或高品质灵宠（传说+）合成时，最终成功率至少70%。装备淬炼和神石炼制不享受此保底。</p>`);bindFurnaceNav17();const mats=()=>[0,1,2,3,4].map(el=>parseGem17($('#divineSlot'+el).value)),preview=()=>{const p=divinePreview17(mats());$('#divinePreview17').innerHTML=`<p>成功 ${(p.success*100).toFixed(2)}% · 有效全队幸运 ${p.luck}<br>${priceText17(p.cost)}<br>${p.reason||'材料就绪；失败不会消耗五枚宝石。'}</p>`;$('#divineDo17').disabled=!p.valid};[0,1,2,3,4].forEach(el=>$('#divineSlot'+el).onchange=preview);$('#divineDo17').onclick=()=>{const r=refineDivine17(mats(),cryptoRoll10,quote10());$('#divineResult17').innerHTML=r?r.success?gemArt(r.gem)+'五行神石诞生！':'神炉未成：五枚宝石仍在包裹中。':'未结算，请检查材料或冷却。';if(r){playForge17('divine',r.success);tone(r.success?1046:164,.35,'triangle');}preview()};preview()}
