function gemResultPanel21(receipt=S.lastGemForge21,replay=false){if(!S||!receipt||!gemReceiptValid21(receipt,S.worldId10))return false;const r=clone10(receipt),g=r.gem||r.materials[0],q=gemQuality17(g);panelContext7={key:'gemResult21',args:[r,replay]};characterSheet13=false;const loss=r.free?'独立体验免消耗：宝石与资源全部保留。':r.success?'投入材料已结算，以下为实际资源消耗。':r.kind==='divine'?'五枚五行宝石完整保留，消耗以下催化资源。':'第一槽主石完整保留；两枚副石及以下资源已消耗。';showDialog(gemHead21(replay?'星辉回响 · 已保存结果':'熔炼结果 · 命运凝光')+`<section class="gem-result21 ${r.success?'success21':'failure21'} q21-${q}" style="--quality:${QUALITIES8[q][1]}"><div class="gem-result-phase21"><small>${replay?'回顾不再扣费':'结算已保存 · 可随时跳过或退出'}</small><h3 id="gemPhase21">灵石蓄能</h3></div>${gemStageHtml21(r.success?'三石归元 · 灵晶新生':'灵光消散 · 主石归来')}<div id="gemOutcome21" class="gem-outcome21" role="status" aria-hidden="true"><h2>${r.success?'✦ 熔炼成功！':'熔炼失败！'}</h2><div class="gem-result-product21">${gemArt(g)}<div><small>${r.success?'成功获得 ×1':r.kind==='divine'?'完整保留五枚主材料':'完整保留主石 ×1'}</small><h3>${GEMS[g.type].name}</h3><b style="color:${QUALITIES8[q][1]}">${gemQualityName21(g)} · ${WX.names[GEMS[g.type].element]}行</b></div></div>${r.success?gemAttrHtml21(g):''}<p class="gem-loss21">${loss}</p>${r.economicMode30==='overlay'?'<p class="overlay30">∞ 独立测试覆盖：本次金币、灵铁、五行材料实扣均为0。宝石原料仍按下方清单真实结算。</p>':gemCostHtml21(r.cost29||r.cost)}<div class="gem-loss-items21">${r.consumed.length?'实际消耗宝石：'+r.consumed.map(g=>escapeHTML(gemName(g))+' ×'+g.count).join('；'):'未消耗宝石材料。'}</div><p>本次真实成功率 ${gemPct21(r.rate)}。${!r.success&&r.kind==='quality'?'失败保护已按新规则累计。':''}</p></div><nav class="gem-result-actions21"><button id="gemSkip21">跳过演出</button><button id="gemConfirm21" class="primary">确认 · 查看宝石包裹</button><button id="gemAgain21">继续熔炼</button></nav></section>`);$('#dialog').classList.add('gems-dialog21','gem-result-dialog21');$('#gemSkip21').onclick=skipGemFx21;$('#gemConfirm21').onclick=gemBagPanel21;$('#gemAgain21').onclick=r.kind==='divine'?gemDivinePanel21:gemForgePanel21;startGemFx21(r);return true}
