gemBuyQuote19=function(g,count){if(!gemValid(g)||g.type>=18||!int10(g.quality,0,2)||g.level!==GEM_RULES21.codec[g.quality]||g.heritage21||!int10(count,1,100))return {valid:false,reason:'商品或购买数量无效。'};const price=gemPrice17(g),stock=(g.quality===2?20:50)-stock17('gem-'+gemKey17(g)),cost=price*count,reason=!atCamp()?'请在安全营地或入口交易。':g.quality===2&&!advancedMarket17()?'稀有货架需实际击败前四关首领并解封五位英雄。':stock<count?'库存不足。':!canPay17({gold:cost})?'金币不足。':!forgeInventory7([{...g,count}])?'包裹或堆叠已满。':'';return {valid:!reason,reason,price,stock,cost,held:gemHeld21(g)}};
